public class TeeRain extends ApplicationAdapter {

    @Override
    public void create() {
    }

    @Override
    public void dispose() {
    }

    @Override
    public void resume() {
    }

    @Override
    public void pause() {
    }

    World mTestWorld;
    boolean mTestBoolean;
    Body mTestStaticBody;
    Fixture mTestStaticFixture;

    @Override
    public void render() {
        if (mTestWorld == null) {
            mTestWorld = new World(new Vector2(0.0f, -10.0f), true);
            mTestWorld.setContactListener(new ContactListener() {

                @Override
                public void beginContact(Contact pContact) {
                    Gdx.app.log("INFO", "BEGINCONTACT");
                    mTestBoolean = true;
                }

                @Override
                public void endContact(Contact pContact) {
                    Gdx.app.log("INFO", "ENDCONTACT");
                }

                @Override
                public void preSolve(Contact pContact, Manifold pOldManifold) {
                }

                @Override
                public void postSolve(Contact pContact, ContactImpulse pImpulse) {
                }
            });
            {
                BodyDef bd = new BodyDef();
                bd.type = BodyType.StaticBody;
                bd.position.x = 0;
                bd.position.y = 0;
                mTestStaticBody = mTestWorld.createBody(bd);
                PolygonShape shape = new PolygonShape();
                shape.setAsBox(0.5f, 0.5f);
                mTestStaticFixture = mTestStaticBody.createFixture(shape, 1.0f);
            }
            {
                BodyDef bd = new BodyDef();
                bd.type = BodyType.DynamicBody;
                bd.position.x = 0;
                bd.position.y = 5;
                Body body = mTestWorld.createBody(bd);
                PolygonShape shape = new PolygonShape();
                shape.setAsBox(0.5f, 0.5f);
                body.createFixture(shape, 1.0f);
            }
        }
        mTestWorld.step(1 / 60f, 8, 8);
        if (mTestBoolean) {
            mTestStaticBody.destroyFixture(mTestStaticFixture);
            mTestBoolean = false;
        }
    }
}
